const ROMANTIC_PALETTE = [
    "#ffffff",
    "#ffe0f0",
    "#ff9ec6",
    "#ff529a",
    "#e066ff",
    "#c77dff",
    "#ff85a1"
];

let isCelebrationActive = false;
let celebrationTime = 0;

class CoupleParticle {
    constructor(nx, ny) {
        this.nx = nx;
        this.ny = ny;
        this.resetPosition();
        this.color = ROMANTIC_PALETTE[Math.floor(Math.random() * ROMANTIC_PALETTE.length)];
        this.size = Math.random() * 1.7 + 1.0;
        this.phase = Math.random() * Math.PI * 2;
        this.shimmerSpeed = Math.random() * 0.04 + 0.02;
        this.brightness = Math.random() * 0.4 + 0.6;
    }

    resetPosition() {
        // Start scattered in cosmic space
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * Math.max(width, height) * 0.8 + 200;
        this.x = width / 2 + Math.cos(angle) * dist;
        this.y = height / 2 + Math.sin(angle) * dist;
        this.vx = 0;
        this.vy = 0;
    }

    update(center, scale, time) {
        // Subtle organic breathing motion
        const breathe = 1 + Math.sin(time * 2.2 + this.phase) * 0.025;
        const targetX = center.x + this.nx * scale * breathe;
        const targetY = center.y + this.ny * scale * breathe;

        // Smooth spring physics convergence
        const dx = targetX - this.x;
        const dy = targetY - this.y;

        this.vx = this.vx * 0.86 + dx * 0.055;
        this.vy = this.vy * 0.86 + dy * 0.055;

        this.x += this.vx;
        this.y += this.vy;

        // Dynamic twinkle
        this.currentAlpha = Math.min(
            1,
            Math.max(0.35, this.brightness + Math.sin(time * 3 + this.phase) * 0.35)
        );
    }

    draw(ctx) {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.globalAlpha = this.currentAlpha;
        ctx.shadowBlur = 8;
        ctx.shadowColor = this.color;
        ctx.fill();
    }
}

// --- Glowing Parametric 3D Heart Formation ---
class HeartHaloParticle {
    constructor(index, total) {
        this.t = (index / total) * Math.PI * 2;
        this.color = index % 2 === 0 ? "#ff4b9b" : "#d88aff";
        this.size = Math.random() * 1.8 + 1.2;
        this.sparklePhase = Math.random() * Math.PI * 2;
    }

    draw(ctx, center, scale, time) {
        // Parametric heart formula
        const sinT = Math.sin(this.t);
        const cosT = Math.cos(this.t);
        const rawX = 16 * Math.pow(sinT, 3);
        const rawY = -(13 * cosT - 5 * Math.cos(2 * this.t) - 2 * Math.cos(3 * this.t) - Math.cos(4 * this.t));

        // Rhythmic heartbeat pulse (double beat: lub-dub)
        const beatCycle = (time * 1.4) % 1;
        let heartPulse = 1;
        if (beatCycle < 0.15) {
            heartPulse = 1 + Math.sin((beatCycle / 0.15) * Math.PI) * 0.14;
        } else if (beatCycle > 0.22 && beatCycle < 0.38) {
            heartPulse = 1 + Math.sin(((beatCycle - 0.22) / 0.16) * Math.PI) * 0.08;
        }

        const hx = center.x + rawX * (scale * 0.034) * heartPulse;
        const hy = center.y + (rawY - 2) * (scale * 0.034) * heartPulse;

        ctx.beginPath();
        ctx.arc(hx, hy, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.globalAlpha = 0.55 + Math.sin(time * 4 + this.sparklePhase) * 0.3;
        ctx.shadowBlur = 14;
        ctx.shadowColor = "#ff4bba";
        ctx.fill();
    }
}

// --- Romantic Heart Fireworks & Sparkles ---
class FireworkSpark {
    constructor(x, y, vx, vy, color, size, decay) {
        this.x = x;
        this.y = y;
        this.vx = vx;
        this.vy = vy;
        this.color = color;
        this.size = size;
        this.alpha = 1;
        this.decay = decay || 0.015;
    }

    update() {
        this.vx *= 0.96;
        this.vy *= 0.96;
        this.vy += 0.04; // Gentle gravity
        this.x += this.vx;
        this.y += this.vy;
        this.alpha -= this.decay;
        return this.alpha > 0;
    }

    draw(ctx) {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.globalAlpha = Math.max(0, this.alpha);
        ctx.shadowBlur = 10;
        ctx.shadowColor = this.color;
        ctx.fill();
    }
}

let fireworkSparks = [];
let fireworkTimer = 0;

function launchHeartFirework(originX, originY) {
    const sparkCount = 65;
    const colors = ["#ff5ca8", "#ff9ec6", "#ffffff", "#ffd166", "#c77dff"];
    const baseColor = colors[Math.floor(Math.random() * colors.length)];
    const speed = Math.random() * 2.5 + 3.5;

    for (let i = 0; i < sparkCount; i++) {
        const t = (i / sparkCount) * Math.PI * 2;
        const sinT = Math.sin(t);
        const cosT = Math.cos(t);
        // Parametric heart velocity profile
        const hx = 16 * Math.pow(sinT, 3);
        const hy = -(13 * cosT - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t));

        const norm = Math.sqrt(hx * hx + hy * hy) || 1;
        const vx = (hx / norm) * speed * (Math.random() * 0.3 + 0.85);
        const vy = (hy / norm) * speed * (Math.random() * 0.3 + 0.85);

        fireworkSparks.push(
            new FireworkSpark(
                originX,
                originY,
                vx,
                vy,
                Math.random() > 0.3 ? baseColor : "#ffffff",
                Math.random() * 2 + 1.2,
                Math.random() * 0.012 + 0.012
            )
        );
    }
}

// --- Floating Stardust ---
let stardustParticles = [];
for (let i = 0; i < 40; i++) {
    stardustParticles.push({
        x: Math.random() * window.innerWidth,
        y: Math.random() * window.innerHeight,
        vy: -(Math.random() * 0.8 + 0.3),
        swaySpeed: Math.random() * 0.02 + 0.01,
        swayDist: Math.random() * 25 + 10,
        baseX: Math.random() * window.innerWidth,
        size: Math.random() * 1.8 + 0.6,
        color: ROMANTIC_PALETTE[Math.floor(Math.random() * ROMANTIC_PALETTE.length)]
    });
}

// Particle Instances
let coupleParticles = [];
let heartHalo = [];

function initCelebration() {
    coupleParticles = COUPLE_POINTS.map(pt => new CoupleParticle(pt[0], pt[1]));

    heartHalo = [];
    const HALO_COUNT = 90;
    for (let i = 0; i < HALO_COUNT; i++) {
        heartHalo.push(new HeartHaloParticle(i, HALO_COUNT));
    }

    // Launch initial celebratory triple fireworks
    launchHeartFirework(width * 0.5, height * 0.45);
    setTimeout(() => launchHeartFirework(width * 0.28, height * 0.38), 350);
    setTimeout(() => launchHeartFirework(width * 0.72, height * 0.38), 700);
}

// --- Main Unified 60fps Animation Loop ---
let lastTime = performance.now();

function animate(currentTime) {
    const dt = (currentTime - lastTime) / 1000;
    lastTime = currentTime;
    celebrationTime += dt;

    ctx.clearRect(0, 0, width, height);

    if (!isCelebrationActive) {
        // Initial soft twinkling stars
        stars.forEach(star => {
            star.opacity += star.speed;
            if (star.opacity > 1 || star.opacity < 0.15) {
                star.speed *= -1;
            }

            ctx.beginPath();
            ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
            ctx.fillStyle = "rgba(255, 225, 255, " + Math.max(0, star.opacity) + ")";
            ctx.shadowBlur = 12;
            ctx.shadowColor = "#e6aaff";
            ctx.fill();
        });
    } else {
        // --- 1. Soft Cosmic Love Nebula Glow ---
        const nebulaRadius = Math.max(width, height) * 0.55;
        const nebulaGrad = ctx.createRadialGradient(
            width / 2,
            height / 2,
            30,
            width / 2,
            height / 2,
            nebulaRadius
        );
        const pulseAlpha = 0.22 + Math.sin(celebrationTime * 2) * 0.06;
        nebulaGrad.addColorStop(0, "rgba(180, 50, 160, " + pulseAlpha + ")");
        nebulaGrad.addColorStop(0.5, "rgba(80, 20, 100, " + (pulseAlpha * 0.5) + ")");
        nebulaGrad.addColorStop(1, "rgba(0, 0, 0, 0)");

        ctx.fillStyle = nebulaGrad;
        ctx.fillRect(0, 0, width, height);

        // --- 2. Twinkling Ambient Cosmic Stars ---
        stars.forEach(star => {
            star.opacity += star.speed;
            if (star.opacity > 1 || star.opacity < 0.15) {
                star.speed *= -1;
            }

            ctx.beginPath();
            ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
            ctx.fillStyle = "rgba(255, 210, 245, " + Math.max(0, star.opacity) + ")";
            ctx.shadowBlur = 10;
            ctx.shadowColor = "#ff77c6";
            ctx.fill();
        });

        // --- 3. Floating Stardust Rising ---
        stardustParticles.forEach(p => {
            p.y += p.vy;
            p.x = p.baseX + Math.sin(celebrationTime * 2 + p.swaySpeed * 100) * p.swayDist;
            if (p.y < -20) {
                p.y = height + 20;
                p.baseX = Math.random() * width;
            }

            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 0.65;
            ctx.shadowBlur = 8;
            ctx.shadowColor = p.color;
            ctx.fill();
        });

        // --- 4. Responsive Scale for Constellation & Heart Halo ---
        // Positioned so the forehead kissing visual and heart halo sit gracefully above the text card
        const coupleCenter = { x: width / 2, y: height * (width < 600 ? 0.33 : 0.35) };
        // Fully responsive scaling: scales comfortably for both mobile and 4K desktop
        const baseDimension = Math.min(width, height);
        const coupleScale = width < 600 ? baseDimension * 0.76 : baseDimension * 0.52;

        // --- 5. Draw Glowing Parametric Heart Halo ---
        ctx.save();
        heartHalo.forEach(h => h.draw(ctx, coupleCenter, coupleScale, celebrationTime));
        ctx.restore();

        // --- 6. Draw Couple Particle Constellation ---
        ctx.save();
        coupleParticles.forEach(p => {
            p.update(coupleCenter, coupleScale, celebrationTime);
            p.draw(ctx);
        });
        ctx.restore();

        // --- 7. Periodic Heart Fireworks ---
        fireworkTimer += dt;
        if (fireworkTimer > 1.8) {
            fireworkTimer = 0;
            const fx = width * (0.2 + Math.random() * 0.6);
            const fy = height * (0.25 + Math.random() * 0.35);
            launchHeartFirework(fx, fy);
        }

        // --- 8. Update & Draw Firework Sparks ---
        ctx.save();
        fireworkSparks = fireworkSparks.filter(spark => {
            const alive = spark.update();
            if (alive) spark.draw(ctx);
            return alive;
        });
        ctx.restore();
    }

    requestAnimationFrame(animate);
}

// --- Triggered by "I LOVE YOU TOO ❤️" button ---
function showLoveMessage(e) {
    if (e) {
        if (typeof e.preventDefault === "function") {
            try { e.preventDefault(); } catch (err) {}
        }
        if (typeof e.stopPropagation === "function") {
            try { e.stopPropagation(); } catch (err) {}
        }
    }

    // Add active celebration class for clean layout transition
    document.body.classList.add("love-celebration-active");
    document.documentElement.classList.add("love-celebration-active");

    const introCard = document.getElementById("page3IntroCard");
    const celebrationContainer = document.getElementById("page3Celebration");
    const message = document.getElementById("loveMessage");
    const button = document.getElementById("loveButton");

    // Hide initial proposal card & button completely
    if (introCard) {
        introCard.style.setProperty("display", "none", "important");
    }
    if (button) {
        button.style.setProperty("display", "none", "important");
        button.style.visibility = "hidden";
        button.style.pointerEvents = "none";
    }

    // Reveal celebration container & response message directly
    if (celebrationContainer) {
        celebrationContainer.classList.remove("hidden");
        celebrationContainer.style.setProperty("display", "flex", "important");
    }
    if (message) {
        message.classList.remove("hidden");
        message.style.setProperty("display", "block", "important");
        message.style.setProperty("visibility", "visible", "important");
        message.style.setProperty("opacity", "1", "important");
        message.style.setProperty("z-index", "9999", "important");
    }

    // Fade out 3D galaxy canvas if present (in all-in-one unified site)
    const webglCanvas = document.querySelector("canvas.webgl");
    if (webglCanvas) {
        webglCanvas.style.opacity = "0";
        webglCanvas.style.pointerEvents = "none";
    }

    // Ensure stars canvas is at 100% full brightness
    const starsCanvas = document.getElementById("stars");
    if (starsCanvas) {
        starsCanvas.style.opacity = "1";
    }

    // Trigger full-screen romantic animation
    if (!isCelebrationActive) {
        isCelebrationActive = true;
        celebrationTime = 0;
        initCelebration();
    }

    // Trigger background music
    startBackgroundMusic();

    // Ensure strict 0 scroll
    window.scrollTo({ top: 0 });
}

function stopCelebration() {
    isCelebrationActive = false;
    celebrationTime = 0;
    fireworks = [];
    heartSparks = [];
    document.body.classList.remove("love-celebration-active");
    document.documentElement.classList.remove("love-celebration-active");

    const introCard = document.getElementById("page3IntroCard");
    const celebrationContainer = document.getElementById("page3Celebration");
    const button = document.getElementById("loveButton");

    if (introCard) {
        introCard.style.removeProperty("display");
    }
    if (button) {
        button.style.removeProperty("display");
        button.style.visibility = "visible";
        button.style.pointerEvents = "auto";
    }
    if (celebrationContainer) {
        celebrationContainer.classList.add("hidden");
        celebrationContainer.style.removeProperty("display");
    }
}

// Expose globally so all onclick or controllers can call it
window.showLoveMessage = showLoveMessage;
window.triggerLoveCelebration = showLoveMessage;
window.stopCelebration = stopCelebration;

// Robust direct event listeners attached to the button
function attachLoveButtonListeners() {
    const button = document.getElementById("loveButton");
    if (button) {
        button.onclick = showLoveMessage;
        button.addEventListener("click", showLoveMessage);
        button.addEventListener("touchend", showLoveMessage);
        button.addEventListener("pointerup", showLoveMessage);
    }
}

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", attachLoveButtonListeners);
} else {
    attachLoveButtonListeners();
}
window.addEventListener("load", attachLoveButtonListeners);

// Window resize
window.addEventListener("resize", resizeCanvas);

// Initialize
resizeCanvas();
requestAnimationFrame(animate);
